  ('e2000000-0000-4000-a000-000000000c1f', 'CO-MAT-00001', 3, 7, 'concurso', 2, 61, 2026, 'multiple_choice', 'Porcentagem', 'Uma loja de Presidente Dutra anuncia um tênis por R$ 370,00. No pagamento à vista, o cliente recebe 12% de desconto. Quanto paga quem compra à vista?', '12% de R$ 370,00 = R$ 44,40. Preço à vista: R$ 370,00 − R$ 44,40 = R$ 325,60. Atalho: multiplicar por 0,88.', 'Calcule 12% do preço e subtraia, ou multiplique o preço por (1 − 0,12).', 'Questão autoral da Educa Mais no estilo dos concursos de prefeituras (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000000c20', 'CO-MAT-00002', 3, 7, 'concurso', 2, 61, 2026, 'multiple_choice', 'Porcentagem', 'Uma loja de Grajaú anuncia um ventilador por R$ 40,00. No pagamento à vista, o cliente recebe 20% de desconto. Quanto paga quem compra à vista?', '20% de R$ 40,00 = R$ 8,00. Preço à vista: R$ 40,00 − R$ 8,00 = R$ 32,00. Atalho: multiplicar por 0,8.', 'Calcule 20% do preço e subtraia, ou multiplique o preço por (1 − 0,2).', 'Questão autoral da Educa Mais no estilo dos concursos de prefeituras (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
